/**
 * The Bridge's two sums over supply house bills, by day (punch list #374).
 *
 * Since a bill can be paid in part, the bill's own row no longer says what is owed on it or when money went on it:
 * - what falls due is what is left on each unpaid bill (`openAmount`), not its whole amount;
 * - what was paid is the lines of the live payments, each on its payment's day. A bill paid in two parts lands on
 *   two days, and a payment that was removed counts nowhere.
 *
 * A credit memo marked used by hand has no payment, so no line: nothing was sent. It still left what is owed on the
 * day it was marked, so the paid sum also takes what a paid bill settled with no line, on its paid day.
 *
 * Pure: no React, no Supabase.
 */
import { calendarYmdInAppTzFromIso } from '../../utils/dateUtils.ts'
import { openAmount, SUPPLY_PAYMENT_TOLERANCE } from '../materials/payments/supplyPayment.ts'

/** An unpaid bill with a due day, as the due read selects it. */
export type SupplyDueRow = { amount: number | null; amount_paid?: number | null; is_paid?: boolean | null; due_date: string | null }

/** What is left on the unpaid bills, by the day each falls due. A bill with nothing left adds no day. */
export function supplyDueByDay(rows: ReadonlyArray<SupplyDueRow>): Map<string, number> {
  const out = new Map<string, number>()
  for (const r of rows) {
    if (!r.due_date) continue
    const open = openAmount(r)
    if (Math.abs(open) <= SUPPLY_PAYMENT_TOLERANCE) continue
    out.set(r.due_date, (out.get(r.due_date) ?? 0) + open)
  }
  return out
}

/** One line of a payment with its payment's day (`YYYY-MM-DD`) and whether that payment was removed. */
export type SupplyPaidLine = { amount: number | null; paid_on: string | null; removed_at?: string | null }

/** A paid bill, for what it settled with no line: its amount, what its lines put on it and when it was marked paid. */
export type SupplyPaidByHandRow = { amount: number | null; amount_paid?: number | null; paid_at: string | null }

/**
 * What went on supply house bills, by company day, inside the window (both ends counted).
 *
 * `lines` are payment lines by their payment's day. `byHand` are the paid bills: each adds only what its lines do not
 * cover (`amount - amount_paid`), on the day it was marked paid, which is nothing for a bill its payments paid.
 */
export function supplyPaidByDayFromLines(input: {
  lines: ReadonlyArray<SupplyPaidLine>
  byHand?: ReadonlyArray<SupplyPaidByHandRow>
  windowStart: string
  todayYmd: string
}): Map<string, number> {
  const { windowStart, todayYmd } = input
  const out = new Map<string, number>()
  const add = (ymd: string, usd: number) => {
    if (ymd < windowStart || ymd > todayYmd) return
    if (Math.abs(usd) <= SUPPLY_PAYMENT_TOLERANCE) return
    out.set(ymd, (out.get(ymd) ?? 0) + usd)
  }
  for (const l of input.lines) {
    if (l.removed_at || !l.paid_on) continue
    add(l.paid_on, Number(l.amount ?? 0))
  }
  for (const b of input.byHand ?? []) {
    if (!b.paid_at) continue
    add(calendarYmdInAppTzFromIso(b.paid_at), Number(b.amount ?? 0) - Number(b.amount_paid ?? 0))
  }
  return out
}
